<template>
  <div>
    <!-- Loading Spinner -->
    <div v-if="loading" class="text-center my-5">
      <div class="spinner-border text-primary" role="status">
        <span class="visually-hidden">Loading...</span>
      </div>
    </div>

    <!-- Error Message -->
    <div v-if="error" class="alert alert-danger">
      {{ error }}
    </div>

    <!-- Book Cards -->
    <div class="row">
      <div
          v-for="book in books"
          :key="book._id"
          class="col-md-4 mb-4"
      >
        <div class="card h-100">
          <div class="text-center p-3">
            <img
                v-if="book.image_url"
                :src="book.image_url"
                :alt="book.book_title"
                class="card-img-top"
                style="max-height: 200px; width: auto;"
                @error="setDefaultImage($event)"
            >
            <img
                v-else
                src="https://via.placeholder.com/150x200?text=No+Image"
                :alt="book.book_title"
                class="card-img-top"
                style="max-height: 200px; width: auto;"
            >
          </div>
          <div class="card-body">
            <h5 class="card-title">{{ book.book_title }}</h5>
            <h6 class="card-subtitle mb-2 text-muted">Type: {{ book.book_type }}</h6>
            <p class="card-text">Price: ${{ book.book_price }}</p>
            <p class="card-text">Quantity: {{ book.book_quantity }}</p>
          </div>
          <div class="card-footer bg-transparent border-top-0">
            <div class="btn-group w-100">
              <router-link :to="`/detail/${book._id}`" class="btn btn-info">
                Details
              </router-link>
              <router-link :to="`/edit/${book._id}`" class="btn btn-warning">
                Edit
              </router-link>
              <button @click="deleteBook(book._id)" class="btn btn-danger">
                Delete
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Empty State -->
    <div v-if="!loading && !error && books.length === 0" class="text-center my-5">
      <p class="lead">No books found. Add some books to get started!</p>
      <router-link to="/add" class="btn btn-primary mt-3">
        Add Book
      </router-link>
    </div>
  </div>
</template>

<script>
import axios from 'axios';

// Create a custom axios instance with CORS configuration
const apiClient = axios.create({
  baseURL: 'https://mduongapi.isharoverwhite.com',
  withCredentials: false,
  headers: {
    'Accept': 'application/json',
    'Content-Type': 'application/json'
  }
});

export default {
  name: 'BookList',
  data() {
    return {
      books: [],
      loading: false,
      error: null
    };
  },
  created() {
    this.fetchBooks();
  },
  methods: {
    async fetchBooks() {
      this.loading = true;
      this.error = null;

      try {
        const response = await apiClient.get('/books');
        this.books = response.data;
        console.log('Books loaded:', this.books); // Debug log
      } catch (err) {
        this.error = 'Failed to load books: ' + err.message;
        console.error('Error fetching books:', err);
      } finally {
        this.loading = false;
      }
    },
    async deleteBook(id) {
      if (!confirm('Are you sure you want to delete this book?')) {
        return;
      }

      this.loading = true;
      try {
        await apiClient.delete(`/books/${id}`);
        // Remove the book from the local array
        this.books = this.books.filter(book => book._id !== id);
      } catch (err) {
        this.error = 'Failed to delete book: ' + err.message;
        console.error('Error deleting book:', err);
      } finally {
        this.loading = false;
      }
    },
    setDefaultImage(event) {
      event.target.src = 'https://via.placeholder.com/150x200?text=Image+Error';
    }
  }
};
</script>

<style scoped>
.card-img-top {
  object-fit: contain;
}
</style>