import Vue from 'vue'
import VueRouter from 'vue-router'
import App from './App.vue'
import home from './view/home.vue'
import addBook from './view/addBook.vue'
import editBook from './view/editBook.vue'
import bookDetail from './view/bookDetail.vue'

// Import Bootstrap
import 'bootstrap/dist/css/bootstrap.css'
import 'bootstrap/dist/js/bootstrap.bundle.js' // This includes Popper.js for dropdowns
import 'bootstrap/dist/js/bootstrap.bundle.min.js'

Vue.config.productionTip = false
Vue.use(VueRouter)

const routes = [
  { path: '/', component: home },
  { path: '/add', component: addBook },
  { path: '/edit/:id', component: editBook },
  { path: '/detail/:id', component: bookDetail },
]

const router = new VueRouter({
  mode: 'history',
  routes
})

new Vue({
  router,
  render: h => h(App),
}).$mount('#app')