<template>
  <div>
    <h2 class="mb-4">Edit Book</h2>

    <!-- Loading Spinner -->
    <div v-if="loading && !book.book_title" class="text-center my-5">
      <div class="spinner-border text-primary" role="status">
        <span class="visually-hidden">Loading...</span>
      </div>
    </div>

    <!-- Error Message -->
    <div v-if="error" class="alert alert-danger">
      {{ error }}
    </div>

    <div v-if="book.book_title" class="card">
      <div class="card-body">
        <form @submit.prevent="submitForm">
          <div class="row">
            <div class="col-md-8">
              <div class="mb-3">
                <label for="book_title" class="form-label">Book Title</label>
                <input
                    type="text"
                    id="book_title"
                    v-model="book.book_title"
                    class="form-control"
                    required
                >
              </div>

              <div class="mb-3">
                <label for="book_type" class="form-label">Book Type</label>
                <input
                    type="text"
                    id="book_type"
                    v-model="book.book_type"
                    class="form-control"
                    required
                >
              </div>

              <div class="mb-3">
                <label for="book_price" class="form-label">Book Price ($)</label>
                <input
                    type="number"
                    id="book_price"
                    v-model="book.book_price"
                    class="form-control"
                    step="0.01"
                    min="0"
                    required
                >
              </div>

              <div class="mb-3">
                <label for="image_url" class="form-label">Book Image URL</label>
                <input
                    type="url"
                    id="image_url"
                    v-model="book.image_url"
                    class="form-control"
                    placeholder="https://example.com/book-image.jpg"
                >
                <small class="form-text text-muted">Enter a URL for the book cover image</small>
              </div>
            </div>

            <div class="col-md-4">
              <div class="mb-3">
                <label class="form-label">Image Preview</label>
                <div class="border rounded p-2 text-center">
                  <img
                      v-if="book.image_url"
                      :src="book.image_url"
                      alt="Book cover preview"
                      class="img-fluid mb-2"
                      style="max-height: 200px;"
                      @error="handleImageError"
                  >
                  <img
                      v-else
                      src="https://via.placeholder.com/150x200?text=No+Image"
                      alt="No image"
                      class="img-fluid mb-2"
                  >
                  <div v-if="imageError" class="text-danger small">
                    {{ imageError }}
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div class="d-flex justify-content-between">
            <button
                type="submit"
                class="btn btn-primary"
                :disabled="loading"
            >
              <span v-if="loading">
                <span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
                Processing...
              </span>
              <span v-else>Update Book</span>
            </button>
            <router-link to="/" class="btn btn-secondary">
              Cancel
            </router-link>
          </div>
        </form>
      </div>
    </div>
  </div>
</template>

<script>
import axios from 'axios';

// Create a custom axios instance with CORS configuration
const apiClient = axios.create({
  baseURL: 'https://mduongapi.isharoverwhite.com',
  withCredentials: false,
  headers: {
    'Accept': 'application/json',
    'Content-Type': 'application/json'
  }
});

export default {
  name: 'EditBookPage',
  data() {
    return {
      book: {
        book_title: '',
        book_type: '',
        book_price: 0,
        image_url: ''
      },
      loading: false,
      error: null,
      imageError: null
    };
  },
  created() {
    this.fetchBook();
  },
  methods: {
    async fetchBook() {
      this.loading = true;
      try {
        const response = await apiClient.get(`/books/${this.$route.params.id}`);
        this.book = response.data;
        // If image_url is not in the response, initialize it
        if (!this.book.image_url) {
          this.book.image_url = '';
        }
        console.log('Book loaded:', this.book); // Debug log
      } catch (err) {
        this.error = 'Failed to load book: ' + err.message;
        console.error('Error fetching book:', err);
      } finally {
        this.loading = false;
      }
    },
    async submitForm() {
      this.loading = true;
      this.error = null;

      try {
        await apiClient.put(`/books/${this.$route.params.id}`, this.book);
        this.$router.push('/');
      } catch (err) {
        this.error = 'Failed to update book: ' + err.message;
        console.error('Error updating book:', err);
      } finally {
        this.loading = false;
      }
    },
    handleImageError() {
      this.imageError = "Failed to load image. Please check the URL.";
    }
  }
};
</script>