<template>
  <div>
    <h2 class="mb-4">Book Details</h2>

    <!-- Loading Spinner -->
    <div v-if="loading && !book.book_title" class="text-center my-5">
      <div class="spinner-border text-primary" role="status">
        <span class="visually-hidden">Loading...</span>
      </div>
    </div>

    <!-- Error Message -->
    <div v-if="error" class="alert alert-danger">
      {{ error }}
    </div>

    <div v-if="book.book_title" class="card">
      <div class="card-header bg-primary text-white">
        <h3 class="mb-0">{{ book.book_title }}</h3>
      </div>
      <div class="card-body">
        <div class="row">
          <div class="col-md-4 text-center mb-4 mb-md-0">
            <img
                v-if="book.image_url"
                :src="book.image_url"
                :alt="book.book_title"
                class="img-fluid rounded"
                style="max-height: 300px;"
                @error="setDefaultImage($event)"
            >
            <img
                v-else
                src="https://via.placeholder.com/200x300?text=No+Image"
                :alt="book.book_title"
                class="img-fluid rounded"
            >
          </div>
          <div class="col-md-8">
            <div class="mb-3">
              <h5 class="card-title">Book Type</h5>
              <p class="card-text">{{ book.book_type }}</p>
            </div>

            <div class="mb-4">
              <h5 class="card-title">Book Price</h5>
              <p class="card-text">${{ book.book_price }}</p>
            </div>

            <div class="d-flex gap-2">
              <router-link :to="`/edit/${book._id}`" class="btn btn-warning">
                Edit
              </router-link>
              <button @click="deleteBook" class="btn btn-danger">
                Delete
              </button>
              <router-link to="/" class="btn btn-secondary">
                Back to List
              </router-link>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import axios from 'axios';

// Create a custom axios instance with CORS configuration
const apiClient = axios.create({
  baseURL: 'https://mduongapi.isharoverwhite.com',
  withCredentials: false,
  headers: {
    'Accept': 'application/json',
    'Content-Type': 'application/json'
  }
});

export default {
  name: 'BookDetailPage',
  data() {
    return {
      book: {},
      loading: false,
      error: null
    };
  },
  created() {
    this.fetchBook();
  },
  methods: {
    async fetchBook() {
      this.loading = true;
      try {
        const response = await apiClient.get(`/books/${this.$route.params.id}`);
        this.book = response.data;
        console.log('Book details loaded:', this.book); // Debug log
      } catch (err) {
        this.error = 'Failed to load book: ' + err.message;
        console.error('Error fetching book:', err);
      } finally {
        this.loading = false;
      }
    },
    async deleteBook() {
      if (!confirm('Are you sure you want to delete this book?')) {
        return;
      }

      this.loading = true;
      try {
        await apiClient.delete(`/books/${this.$route.params.id}`);
        this.$router.push('/');
      } catch (err) {
        this.error = 'Failed to delete book: ' + err.message;
        console.error('Error deleting book:', err);
      } finally {
        this.loading = false;
      }
    },
    setDefaultImage(event) {
      event.target.src = 'https://via.placeholder.com/200x300?text=Image+Error';
    }
  }
};
</script>